def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    key=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,8)]
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==8]
    if not key or not cells:return out
    # The key is a set of colored polyominoes; each key cell expands to a block
    # whose side matches the canvas unit (4x4 for this instance).
    s=4 if h<=16 else 3
    r0=min(r for r,c in cells);c0=min(c for r,c in cells)
    tiles={( (r-r0)//s,(c-c0)//s) for r,c in cells}
    # Find connected key pieces by color.
    seen=set(); pieces=[]
    for r,c,v in key:
        if (r,c) in seen:continue
        q=[(r,c)];seen.add((r,c));comp=[]
        while q:
            y,x=q.pop();comp.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(y+dy,x+dx)
                if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==v and p not in seen:
                    seen.add(p);q.append(p)
        a=min(y for y,x in comp);b=min(x for y,x in comp)
        pieces.append((v,tuple(sorted((y-a,x-b) for y,x in comp))))
    placements=[]
    for col,shape in pieces:
        forms=set()
        for flip in (1,-1):
            for rot in range(4):
                pts=[]
                for y,x in shape:
                    x*=flip
                    for _ in range(rot):y,x=x,-y
                    pts.append((y,x))
                a=min(y for y,x in pts);b=min(x for y,x in pts)
                forms.add(tuple(sorted((y-a,x-b) for y,x in pts)))
        for form in forms:
            for a in range(max(r for r,c in tiles)+1):
                for b in range(max(c for r,c in tiles)+1):
                    p=frozenset((a+y,b+x) for y,x in form)
                    if p and p<=tiles:placements.append((p,col))
    by={t:[] for t in tiles}
    for p,col in placements:
        for t in p:by[t].append((p,col))
    def solve(rem,ans):
        if not rem:return ans
        t=min(rem,key=lambda z:sum(p<=rem for p,col in by[z]))
        for p,col in by[t]:
            if p<=rem:
                result=solve(rem-p,ans+[(p,col)])
                if result is not None:return result
        return None
    solution=solve(tiles,[])
    if solution:
        for p,col in solution:
            for tr,tc in p:
                for dy in range(s):
                    for dx in range(s):
                        y=r0+tr*s+dy;x=c0+tc*s+dx
                        if y<h and x<w and grid[y][x]==8:out[y][x]=col
    return out
